/**
 * @module supabase/storage
 * @description Gestió de fitxers amb Supabase Storage.
 * @contract
 *   - uploadFile(bucket, path, file)
 *   - downloadFile(bucket, path)
 *   - deleteFile(bucket, path)
 *   - listFiles(bucket, path)
 *   - getPublicUrl(bucket, path)
 *   - resolveAsset(ref)
 *   - promoteToPublic(ref)
 */

import { getResolvedConfig } from './runtime.js';
import { getClient } from './config.js';
import { usuariDeSessio } from '../identitat.js';
import { handleError } from './utils.js';
import { CODI_BACKEND_INABASTABLE, CODI_MITJANS, esBackendInabastable } from '../errorsBackend.js';

/* Límits per fitxer (ARQ-G07): 25 MiB al bucket privat, 5 MiB al públic. */
const MIDA_MAX_PRIVADA = 26214400;
const MIDA_MAX_PUBLICA = 5242880;

/* F2 (ordre del Mestre, 261004; pla 2045, Marató 2230) · El rebuig d'una pujada.
   Abans es llegia `handleError(error)?.message`, que no existix mai: handleError
   torna `{error, code, details}`, sense `message` (utils.js:18; xat.js:63 fa el
   mateix rodeig), i qualsevol causa eixia com el mateix
   «No s’ha pogut pujar el fitxer». Ara el rebuig de Storage es traduïx al
   vocabulari neutral del port (errorsBackend.js): el codi va a `error.codi` i el
   text, en valencià, conserva el prefix de sempre perquè es puga buscar. Cap text
   porta la ruta, l'uid, el poble ni el missatge cru del proveïdor; l'original
   queda a `cause` per a qui depure. */
const PREFIX_PUJADA = 'No s’ha pogut pujar el fitxer:';
const TEXTOS_PUJADA = Object.freeze({
  [CODI_BACKEND_INABASTABLE]: 'el servidor no respon. Comprova la connexió i torna-ho a provar.',
  [CODI_MITJANS.SESSIO]: 'la sessió ha caducat. Torna a entrar i repeteix-ho.',
  [CODI_MITJANS.SENSE_ESPAI]: 'el servidor encara no té preparat l’espai de fitxers.',
  [CODI_MITJANS.SENSE_PERMIS]: 'el servidor no t’ha donat permís per a guardar-lo ací.',
  [CODI_MITJANS.MASSA_GRAN]: 'passa del límit de mida del servidor.',
  [CODI_MITJANS.FORMAT]: 'el servidor no admet este format.',
  [CODI_MITJANS.SERVIDOR]: 'el servidor ha fallat; torna-ho a provar d’ací a un moment.'
});

/* Storage pot respondre HTTP 400 amb el codi real al cos (statusCode '403' o
   '404'), segons la versió: es miren tots dos, en eixe ordre. */
const estatsHttp = (error) => [error?.status, error?.statusCode].map(Number).filter((n) => n >= 100 && n <= 599);

function codiDePujada(error) {
  // storage-js conserva el codi del servei tant a code com, en versions
  // antigues, a statusCode. Només traduïm codis exactes, mai noms de fitxer.
  const codis = {
    InvalidJWT: CODI_MITJANS.SESSIO,
    NoSuchBucket: CODI_MITJANS.SENSE_ESPAI,
    AccessDenied: CODI_MITJANS.SENSE_PERMIS,
    EntityTooLarge: CODI_MITJANS.MASSA_GRAN,
    InvalidMimeType: CODI_MITJANS.FORMAT
  };
  for (const codi of [error?.code, error?.statusCode]) {
    if (typeof codi === 'string' && Object.hasOwn(codis, codi)) return codis[codi];
  }
  const missatge = typeof error?.message === 'string' ? error.message.trim() : '';
  const estats = estatsHttp(error).filter(Number.isInteger);
  const xarxa = /^(?:Failed to fetch|Load failed|Network request failed|NetworkError(?: when attempting to fetch resource\.)?)$/i;
  const senseResposta = (candidat) => esBackendInabastable(candidat)
    && (candidat?.status === 0 || candidat?.name !== 'TypeError' || xarxa.test(String(candidat.message || '').trim()));
  // Un error JSON o un path amb «fetch» no prova una fallada de connexió.
  if (!estats.length && (senseResposta(error) || senseResposta(error?.originalError)
    || (error?.name === 'StorageUnknownError' && xarxa.test(missatge)))) return CODI_BACKEND_INABASTABLE;

  // El cos és la resposta específica de Storage: HTTP400 pot portar403/404.
  const cos = Number(error?.statusCode);
  const http = Number(error?.status);
  const valid = (n) => Number.isInteger(n) && n >= 100 && n <= 599;
  const estat = valid(cos) ? cos : (valid(http) ? http : undefined);
  const jwtAntic = /^(?:"exp" claim timestamp check failed|JWT (?:expired|is expired|malformed)|invalid signature|Invalid Compact JWS|(?:invalid|malformed) JWT(?:: (?:token has expired|token is expired|invalid signature))?)$/i.test(missatge);
  // Kong rebutja la clau pública: una altra sessió no repara la configuració.
  if ([undefined, 400, 401].includes(estat) && /^(?:Invalid API key|No API key found in request)$/i.test(missatge)) return CODI_MITJANS.DESCONEGUT;
  if (estat === 401) return CODI_MITJANS.SESSIO;
  // Compatibilitat antiga: el JWT caducat podia arribar com403 sense code.
  if (estat === 403) return jwtAntic ? CODI_MITJANS.SESSIO : CODI_MITJANS.SENSE_PERMIS;
  if (estat === 404) return CODI_MITJANS.SENSE_ESPAI;
  if (estat === 413) return CODI_MITJANS.MASSA_GRAN;
  if (estat === 415) return CODI_MITJANS.FORMAT;
  if (estat >= 500) return CODI_MITJANS.SERVIDOR;
  // ForaHTTP400 no endevinem una causa contradictòria pel text cru.
  if (estat !== undefined && estat !== 400) return CODI_MITJANS.DESCONEGUT;

  // Fallback per servidors antics: missatges complets i ancorats, només
  // sense estat específic. El text original continua exclusivament a cause.
  if (jwtAntic) return CODI_MITJANS.SESSIO;
  if (/^(?:Bucket not found|NoSuchBucket)$/i.test(missatge)) return CODI_MITJANS.SENSE_ESPAI;
  if (/^(?:Unauthorized|AccessDenied|Access denied|new row violates row-level security policy(?: for table "[^"]+")?)$/i.test(missatge)) return CODI_MITJANS.SENSE_PERMIS;
  if (/^(?:EntityTooLarge|The object exceeded the maximum allowed size|maximum allowed size exceeded)$/i.test(missatge)) return CODI_MITJANS.MASSA_GRAN;
  if (/^(?:InvalidMimeType|mime type [a-z0-9.+-]+\/[a-z0-9.+-]+ is not supported)$/i.test(missatge)) return CODI_MITJANS.FORMAT;
  return CODI_MITJANS.DESCONEGUT;
}

/**
 * Traduïx el rebuig d'una pujada a un Error amb `codi` neutral (CODI_MITJANS o
 * CODI_BACKEND_INABASTABLE), `status` HTTP si n'hi ha i l'original a `cause`.
 * Funció pura: no escriu enlloc. Una resposta que no reconeix (una versió nova
 * de l'API, per exemple) cau a DESCONEGUT amb l'estat HTTP, en lloc d'endevinar.
 * @param {object} error - L'error de Storage (StorageApiError o StorageUnknownError).
 * @returns {Error}
 */
export function errorDePujada(error) {
  const codi = codiDePujada(error);
  const [status] = estatsHttp(error);
  const detall = codi === CODI_MITJANS.DESCONEGUT
    ? `error inesperat${status ? ` del servidor (HTTP ${status})` : ''}.`
    : TEXTOS_PUJADA[codi];
  return Object.assign(new Error(`${PREFIX_PUJADA} ${detall}`, { cause: error }), { codi, status });
}

/**
 * Puja un fitxer a un bucket.
 * @param {string} bucket - Nom del bucket.
 * @param {string} path - Camí dins el bucket.
 * @param {File|Blob} file - Fitxer a pujar.
 * @param {object} config - Configuració
 * @returns {Promise<{data: object, error: object}>}
 */
export const uploadFile = async (bucket, path, file, config = {}) => {
  try {
    const supabase = await getClient(config);
    return await supabase.storage.from(bucket).upload(path, file);
  } catch (error) {
    return handleError(error);
  }
};

/**
 * Baixa un fitxer.
 * @param {string} bucket - Nom del bucket.
 * @param {string} path - Camí dins el bucket.
 * @param {object} config - Configuració
 * @returns {Promise<{data: Blob, error: object}>}
 */
export const downloadFile = async (bucket, path, config = {}) => {
  try {
    const supabase = await getClient(config);
    return await supabase.storage.from(bucket).download(path);
  } catch (error) {
    return handleError(error);
  }
};

/**
 * Elimina un fitxer o múltiples fitxers d'un bucket.
 * @param {string} bucket - Nom del bucket.
 * @param {string|string[]} pathOrPaths - Camí o array de camins dins el bucket.
 * @param {object} config - Configuració
 * @returns {Promise<{data: object, error: object}>}
 */
export const deleteFile = async (bucket, pathOrPaths, config = {}) => {
  try {
    const supabase = await getClient(config);
    const paths = Array.isArray(pathOrPaths) ? pathOrPaths : [pathOrPaths];
    return await supabase.storage.from(bucket).remove(paths);
  } catch (error) {
    return handleError(error);
  }
};

/**
 * Llista els fitxers d'un bucket.
 * @param {string} bucket - Nom del bucket.
 * @param {string} path - Camí dins el bucket (opcional).
 * @param {object} config - Configuració
 * @returns {Promise<{data: Array, error: object}>}
 */
export const listFiles = async (bucket, path = '', config = {}) => {
  try {
    const supabase = await getClient(config);
    return await supabase.storage.from(bucket).list(path);
  } catch (error) {
    return handleError(error);
  }
};

/**
 * Obté l'URL pública d'un fitxer.
 * @param {string} bucket - Nom del bucket.
 * @param {string} path - Camí dins el bucket.
 * @param {object} config - Configuració
 * @returns {Promise<string>}
 */
export const getPublicUrl = async (bucket, path, config = {}) => {
  const supabase = await getClient(config);
  return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl;
};

/**
 * Puja un fitxer al bucket per defecte de mitjans o mitjans_privats, complint el contracte.
 * @param {File} fitxer
 * @param {object} options
 * @param {object} config
 */
export const uploadToStorage = async (fitxer, { carpeta = 'general', tenantId } = {}, config = {}) => {
  const user = usuariDeSessio();
  if (!user?.id) throw new Error('Cal iniciar sessió');
  const resolvedTenant = getResolvedConfig(config).tenantId;
  if (tenantId && resolvedTenant && tenantId !== resolvedTenant) throw new Error('Poble inconsistent');
  const selectedTenant = tenantId || resolvedTenant;
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (!uuid.test(selectedTenant || '') || !uuid.test(user.id)) throw new Error('Poble o usuari invàlid');
  if (!/^[a-z0-9_-]{1,40}$/.test(carpeta)) throw new Error('Carpeta invàlida');
  const extensions = { 'image/webp': 'webp', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/avif': 'avif', 'application/pdf': 'pdf' };
  const isPrivate = carpeta === 'notes';
  if (!(fitxer instanceof Blob) || !extensions[fitxer.type] || (!isPrivate && fitxer.type === 'application/pdf'))
    throw new Error('Format de fitxer no admés en este destí');
  if (!fitxer.size || fitxer.size > (isPrivate ? MIDA_MAX_PRIVADA : MIDA_MAX_PUBLICA)) throw new Error('Mida de fitxer no admesa');
  const bucket = isPrivate ? 'mitjans_privats' : 'mitjans';
  const ruta = `${selectedTenant.toLowerCase()}/${user.id.toLowerCase()}/${carpeta}/${crypto.randomUUID()}.${extensions[fitxer.type]}`;
  const client = await getClient(config);
  const { error } = await client.storage.from(bucket).upload(ruta, fitxer, { upsert: false });
  if (error) {
    const rebuig = errorDePujada(error);
    // F2 · Per a diagnosi, només codis: ni la ruta, ni l'uid, ni el poble.
    console.warn('[Storage] pujada rebutjada', { codi: rebuig.codi, status: Number.isInteger(rebuig.status) ? rebuig.status : undefined });
    throw rebuig;
  }
  return { url: `sdp-media://${bucket}/${ruta}`, ruta };
};

/**
 * Resol un actiu (asset) a la seua URL real (pública o firmada temporal).
 * @param {string} ref - Referència opaca, ex. sdp-media://mitjans_privats/tenant_id/user_id/...
 * @param {object} config
 */
export const resolveAsset = async (ref, config = {}) => {
  if (!ref || typeof ref !== 'string') return ref;
  if (!ref.startsWith('sdp-media://')) return ref; // Backwards compatibility

  const pathPart = ref.replace('sdp-media://', '');
  const slashIndex = pathPart.indexOf('/');
  if (slashIndex === -1) return ref;

  const bucket = pathPart.substring(0, slashIndex);
  const path = pathPart.substring(slashIndex + 1);

  const supabase = await getClient(config);

  if (bucket === 'mitjans_privats') {
    // URL firmada amb 1 hora de duració (3600 segons)
    const { data, error } = await supabase.storage.from(bucket).createSignedUrl(path, 3600);
    if (error) {
      console.warn("[Storage] No s'ha pogut generar URL firmada per", path, error);
      return ref;
    }
    return data.signedUrl;
  } else {
    return supabase.storage.from(bucket).getPublicUrl(path).data.publicUrl;
  }
};

/**
 * Promou un actiu privat a públic, movent-lo del bucket privat al públic.
 * @param {string} ref - Referència opaca de mitjans_privats
 * @param {object} config
 * @returns {Promise<string>} La nova referència promoguda
 */
export const promoteToPublic = async (ref, config = {}) => {
  if (!ref || typeof ref !== 'string') return ref;
  if (!ref.startsWith('sdp-media://mitjans_privats/')) return ref; 

  const path = ref.replace('sdp-media://mitjans_privats/', '');

  // 1. Descarreguem l'arxiu des del bucket privat
  const { data: fileData, error: downloadError } = await downloadFile('mitjans_privats', path, config);
  if (downloadError) {
    console.warn("[Storage] Error baixant el fitxer per a promoure'l", downloadError);
    return ref; // Deixem l'original
  }

  // 2. El pugem al bucket públic en la mateixa ruta
  const { error: uploadError } = await uploadFile('mitjans', path, fileData, config);
  if (uploadError) {
    console.warn("[Storage] Error pujant el fitxer al promoure'l", uploadError);
    return ref; 
  }

  // C17 (Auditoria): No esborrem l'original per evitar pèrdua de dades si falla 
  // la persistència de la nova referència o la publicació al Mur.
  // await deleteFile('mitjans_privats', path, config);

  return `sdp-media://mitjans/${path}`;
};

// @vitest-environment node
/* F2 (ordre del Mestre, 261004; pla 2045, Marató 2230) · Pujada d'avatars.
   Abans, qualsevol rebuig de Storage (xarxa, bucket absent, RLS, JWT, mida,
   format o 5xx) eixia com el mateix «No s’ha pogut pujar el fitxer», perquè
   storage.js llegia un `message` que handleError no torna mai. Estes proves
   fixen la traducció al vocabulari neutral del port (CODI_MITJANS), l'ordre de
   classificació (el JWT abans del 403) i que el missatge no porta ni la ruta,
   ni l'uid, ni el poble, ni el text cru del proveïdor. */
import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';

const m = vi.hoisted(() => ({ upload: vi.fn(), usuari: null }));
vi.mock('./runtime.js', () => ({ getResolvedConfig: (config = {}) => ({ ...config }) }));
vi.mock('./config.js', () => ({ getClient: async () => ({ storage: { from: (bucket) => ({ upload: (...args) => m.upload(bucket, ...args) }) } }) }));
vi.mock('../identitat.js', () => ({ usuariDeSessio: () => m.usuari }));

import { errorDePujada, uploadToStorage } from './storage.js';
import { CODI_BACKEND_INABASTABLE, CODI_MITJANS, esBackendInabastable } from '../errorsBackend.js';

const LITERAL_SOL = 'No s’ha pogut pujar el fitxer';
const PREFIX = `${LITERAL_SOL}: `;
const UID = '11111111-1a1a-4000-8000-000000000001';
const POBLE = '22222222-2b2b-4000-8000-000000000002';

/* Les dues formes de storage-js 2.x: StorageApiError (el servidor ha respost;
   `status` és l'HTTP i `statusCode` ve del cos) i StorageUnknownError (no hi ha
   resposta; porta l'error de fetch a `originalError`). */
const errorApi = (message, status, statusCode, code) =>
  Object.assign(new Error(message), { name: 'StorageApiError', __isStorageError: true, status, statusCode, code });
const errorSenseResposta = (message, originalError) =>
  Object.assign(new Error(message), { name: 'StorageUnknownError', __isStorageError: true, originalError });

const CASOS = [
  ['RLS amb HTTP 400 i statusCode 403', errorApi('new row violates row-level security policy', 400, '403'), CODI_MITJANS.SENSE_PERMIS],
  ['403 real amb AccessDenied', errorApi('', 403, undefined, 'AccessDenied'), CODI_MITJANS.SENSE_PERMIS],
  ['bucket absent amb HTTP 400 i statusCode 404', errorApi('Bucket not found', 400, '404'), CODI_MITJANS.SENSE_ESPAI],
  ['JWT caducat amb statusCode 403: sessió, no permís', errorApi('"exp" claim timestamp check failed', 400, '403'), CODI_MITJANS.SESSIO],
  ['JWT invàlid pel codi del cos', errorApi('invalid signature', 400, '400', 'InvalidJWT'), CODI_MITJANS.SESSIO],
  ['401', errorApi('Unauthorized', 401, '401'), CODI_MITJANS.SESSIO],
  ['413', errorApi('', 413), CODI_MITJANS.MASSA_GRAN],
  ['massa gran pel codi del cos', errorApi('The object exceeded the maximum allowed size', 400, '413', 'EntityTooLarge'), CODI_MITJANS.MASSA_GRAN],
  ['415 per MIME', errorApi('mime type image/webp is not supported', 415, '415', 'InvalidMimeType'), CODI_MITJANS.FORMAT],
  ['502', errorApi('Bad Gateway', 502, '502'), CODI_MITJANS.SERVIDOR],
  ['fetch sense resposta', errorSenseResposta('Failed to fetch', new TypeError('Failed to fetch')), CODI_BACKEND_INABASTABLE],
  ['Safari sense resposta', errorSenseResposta('Load failed', new TypeError('Load failed')), CODI_BACKEND_INABASTABLE],
  ['418 sense traducció', errorApi('I am a teapot', 418, '418'), CODI_MITJANS.DESCONEGUT],
  ['413 amb jwt al path no és sessió', errorApi('Object path users/jwt/avatar.png exceeds maximum allowed size', 413, '413'), CODI_MITJANS.MASSA_GRAN],
  ['500 amb Unauthorized al path no és permís', errorApi('Internal failure at object path users/Unauthorized/avatar.png', 500, '500'), CODI_MITJANS.SERVIDOR],
  ['403 amb jwt al path conserva permís', errorApi('Object path users/jwt/avatar.png is not accessible', 403, '403'), CODI_MITJANS.SENSE_PERMIS],
  ['HTTP400/body413 preval sobre jwt al path', errorApi('Object path users/jwt/avatar.png', 400, '413'), CODI_MITJANS.MASSA_GRAN],
  ['NoSuchBucket sense missatge', errorApi('', 400, undefined, 'NoSuchBucket'), CODI_MITJANS.SENSE_ESPAI],
  ['NoSuchBucket antic a statusCode', errorApi('', 400, 'NoSuchBucket'), CODI_MITJANS.SENSE_ESPAI],
  ['InvalidJWT amb403 és sessió', errorApi('', 403, '403', 'InvalidJWT'), CODI_MITJANS.SESSIO],
  ['InvalidJWT antic a statusCode', errorApi('', 400, 'InvalidJWT'), CODI_MITJANS.SESSIO],
  ['un code que conté InvalidJWT no és el codi exacte', errorApi('Object upload failed', 413, '413', 'ObjectKeyInvalidJWT'), CODI_MITJANS.MASSA_GRAN],
  ['JWT expired antic sense code', errorApi('JWT expired', 400, '400'), CODI_MITJANS.SESSIO],
  ['JWT expired antic amb403', errorApi('JWT expired', 403, '403'), CODI_MITJANS.SESSIO],
  ['un path amb JWT expired no és el missatge antic', errorApi('Object path users/JWT expired/avatar.png', 403, '403'), CODI_MITJANS.SENSE_PERMIS],
  ['estat418 no es traduïx pel text de jwt', errorApi('JWT expired', 418, '418'), CODI_MITJANS.DESCONEGUT],
  ['UnknownError amb fetch en JSON no és connexió', errorSenseResposta('Unexpected JSON while reading fetch/avatar', new SyntaxError('x')), CODI_MITJANS.DESCONEGUT],
  ['TypeError amb Failed to fetch dins un path no és connexió', new TypeError('Cannot read object path Failed to fetch/avatar'), CODI_MITJANS.DESCONEGUT],
  ['NetworkError Firefox exacte sense resposta', errorSenseResposta('NetworkError when attempting to fetch resource.', new TypeError('NetworkError when attempting to fetch resource.')), CODI_BACKEND_INABASTABLE],
  ['bucket antic ancorat ambHTTP400', errorApi('Bucket not found', 400, '400'), CODI_MITJANS.SENSE_ESPAI],
  ['path amb Bucket not found no és bucket absent', errorApi('Object path users/Bucket not found/avatar.png', 400, '400'), CODI_MITJANS.DESCONEGUT],
  ['500 amb Invalid API key al path continua servidor', errorApi('Object path users/Invalid API key/avatar.png', 500, '500'), CODI_MITJANS.SERVIDOR],
  ['401 amb API key al path no és rebuig de Kong', errorApi('Object path users/API key/avatar.png', 401, '401'), CODI_MITJANS.SESSIO],
  ['legacy invalid signature dins un path no és sessió', errorApi('Object path users/invalid signature/avatar.png', 400, '400'), CODI_MITJANS.DESCONEGUT],
  ['el codi numèric del cos preval sobre HTTP genèric', errorApi('Object upload failed', 403, '500'), CODI_MITJANS.SERVIDOR]
];

describe('errorDePujada · taula de classificació', () => {
  test.each(CASOS)('%s', (_nom, cru, codi) => {
    const error = errorDePujada(cru);
    expect(error).toBeInstanceOf(Error);
    expect(error.codi).toBe(codi);
    expect(error.cause).toBe(cru);
    expect(error.message.startsWith(PREFIX)).toBe(true);
    // Cap text cru del proveïdor arriba a la vista (errorsBackend.js:2-5).
    if (cru.message) expect(error.message).not.toContain(cru.message);
    if (cru.code) expect(error.message).not.toContain(cru.code);
  });

  test('el desconegut porta només l’estat HTTP; sense estat, cap número inventat', () => {
    expect(errorDePujada(errorApi('I am a teapot', 418, '418'))).toMatchObject({
      codi: CODI_MITJANS.DESCONEGUT, status: 418, message: `${PREFIX}error inesperat del servidor (HTTP 418).`
    });
    const senseEstat = errorDePujada(errorSenseResposta('Unexpected token < in JSON', new SyntaxError('x')));
    expect(senseEstat.codi).toBe(CODI_MITJANS.DESCONEGUT);
    expect(senseEstat.message).toBe(`${PREFIX}error inesperat.`);
    expect(senseEstat.status).toBeUndefined();
  });

  test('una pujada sense resposta és «inabastable» per a tot el port', () => {
    const error = errorDePujada(errorSenseResposta('Failed to fetch', new TypeError('Failed to fetch')));
    expect(esBackendInabastable(error)).toBe(true);
    expect(esBackendInabastable(errorDePujada(errorApi('Bad Gateway', 502, '502')))).toBe(false);
  });

  test('el vocabulari està congelat i no repetix cap codi', () => {
    expect(Object.isFrozen(CODI_MITJANS)).toBe(true);
    const codis = Object.values(CODI_MITJANS);
    expect(new Set([...codis, CODI_BACKEND_INABASTABLE]).size).toBe(codis.length + 1);
  });
});

/* Poliment F2 (revisió de Codex, Marató 2230) · Cada branca de codiDePujada,
   sola: un cas que només casa per l'estat i un altre que només casa pel text,
   perquè llevar qualsevol de les dos meitats d'una condició tombe una prova. */
const BRANQUES = [
  // Xarxa: el propi error (sense embolcall) i només l'originalError (embolcall mut).
  ['xarxa · el propi error porta el codi neutral', Object.assign(new Error('provider-private-payload-not-for-ui'), { codi: CODI_BACKEND_INABASTABLE }), CODI_BACKEND_INABASTABLE],
  ['xarxa · el propi error porta l’estat 0', Object.assign(new Error('provider-private-payload-not-for-ui'), { status: 0 }), CODI_BACKEND_INABASTABLE],
  ['xarxa · el TypeError de fetch cru, sense embolcall', new TypeError('Failed to fetch'), CODI_BACKEND_INABASTABLE],
  ['xarxa · només l’originalError: Firefox amb l’embolcall mut', errorSenseResposta('error opac', new TypeError('NetworkError when attempting to fetch resource.')), CODI_BACKEND_INABASTABLE],
  ['xarxa · només l’originalError: React Native amb l’embolcall mut', errorSenseResposta('error opac', new TypeError('Network request failed')), CODI_BACKEND_INABASTABLE],
  // Espai: l'estat sol i el text sol.
  ['espai · 404 sense «Bucket not found»', errorApi('', 404), CODI_MITJANS.SENSE_ESPAI],
  ['espai · «Bucket not found» sense 404', errorApi('Bucket not found', 400, '400'), CODI_MITJANS.SENSE_ESPAI],
  ['espai · NoSuchBucket sense 404', errorApi('', 400, '400', 'NoSuchBucket'), CODI_MITJANS.SENSE_ESPAI],
  // Format: l'estat sol i el text sol.
  ['format · 415 sol', errorApi('', 415), CODI_MITJANS.FORMAT],
  ['format · «mime type» sol', errorApi('mime type text/html is not supported', 400, '400'), CODI_MITJANS.FORMAT],
  /* Sessió: el Storage antic respon {statusCode: '400', error: 'Invalid JWT',
     message: …} sense `code`, i storage-js 2.112 en conserva només `message`. */
  ['sessió · JWT antic tal com el construïx storage-js', errorApi('invalid signature', 400, '400'), CODI_MITJANS.SESSIO],
  ['sessió · JWS mal format del Storage antic', errorApi('Invalid Compact JWS', 400, '400'), CODI_MITJANS.SESSIO],
  ['sessió · el cos cru del Storage antic', { statusCode: '400', error: 'Invalid JWT', message: 'invalid signature' }, CODI_MITJANS.SESSIO],
  // Configuració: la clau pública rebutjada per Kong no és la sessió.
  ['configuració · 401 «Invalid API key»', errorApi('Invalid API key', 401, '401'), CODI_MITJANS.DESCONEGUT],
  ['configuració · 401 «No API key found in request»', errorApi('No API key found in request', 401, '401'), CODI_MITJANS.DESCONEGUT],
  /* No són «el servidor no respon», encara que l'embolcall diga «fetch»: un
     TypeError d'argument (bug del client) i l'AbortError de Safari. */
  ['no inabastable · TypeError d’argument de fetch', errorSenseResposta("Failed to execute 'fetch' on 'Window': Invalid value", new TypeError("Failed to execute 'fetch' on 'Window': Invalid value")), CODI_MITJANS.DESCONEGUT],
  ['no inabastable · AbortError de Safari', errorSenseResposta('Fetch is aborted', new DOMException('Fetch is aborted', 'AbortError')), CODI_MITJANS.DESCONEGUT]
];

describe('errorDePujada · cada branca, sola', () => {
  test.each(BRANQUES)('%s', (_nom, cru, codi) => {
    const error = errorDePujada(cru);
    expect(error.codi).toBe(codi);
    expect(error.cause).toBe(cru);
    expect(error.message.startsWith(PREFIX)).toBe(true);
    if (cru.message) expect(error.message).not.toContain(cru.message);
    expect(esBackendInabastable(error)).toBe(codi === CODI_BACKEND_INABASTABLE);
  });

  test('la clau pública rebutjada porta l’estat HTTP i no parla de la sessió', () => {
    const error = errorDePujada(errorApi('Invalid API key', 401, '401'));
    expect(error).toMatchObject({ codi: CODI_MITJANS.DESCONEGUT, status: 401, message: `${PREFIX}error inesperat del servidor (HTTP 401).` });
    expect(error.message).not.toContain('sessió');
  });

  test('l’AbortError i el TypeError d’argument cauen a «error inesperat», sense estat', () => {
    for (const nom of ['no inabastable · TypeError d’argument de fetch', 'no inabastable · AbortError de Safari']) {
      const [, cru] = BRANQUES.find(([n]) => n === nom);
      expect(errorDePujada(cru)).toMatchObject({ message: `${PREFIX}error inesperat.`, status: undefined });
    }
  });

  test('el JWT antic conserva l’estat HTTP 400 i diu que la sessió no val', () => {
    const error = errorDePujada({ statusCode: '400', error: 'Invalid JWT', message: 'invalid signature' });
    expect(error).toMatchObject({ codi: CODI_MITJANS.SESSIO, status: 400, message: `${PREFIX}la sessió ha caducat. Torna a entrar i repeteix-ho.` });
  });
});

describe('regressió · el literal sol ja no pot eixir', () => {
  test.each([...CASOS.map(([nom, cru]) => [nom, cru]), ['null', null], ['objecte buit', {}], ['text', 'error']])('%s', (_nom, cru) => {
    const { message } = errorDePujada(cru);
